import { ApiPropertyOptional } from '@nestjs/swagger';
import { IsDateString, IsOptional } from 'class-validator';

// -----------------------------------------------------------------------------
// sisiMove — Start Journey DTO
// -----------------------------------------------------------------------------
//
// HTTP request body for starting a Journey.
//
// The following values are intentionally NOT part of this DTO:
// - journeyPublicId → supplied by the route parameter
// - correlationId   → generated by the controller
// - causationId     → application-layer concern
//
// The controller/application layer constructs the StartJourneyCommand from
// the validated HTTP input.
//
// -----------------------------------------------------------------------------

export class StartJourneyDto {
  // ---------------------------------------------------------------------------
  // Start Timestamp
  // ---------------------------------------------------------------------------

  @ApiPropertyOptional({
    example: '2026-08-15T10:00:00.000Z',
    description:
      'Optional effective journey start timestamp. When omitted, the backend uses the current time.',
    format: 'date-time',
  })
  @IsOptional()
  @IsDateString()
  readonly startedAt?: string;
}
